                // Get only show_archived and show_other_users, not other filters that would conflict
                let saved_settings = '';
                const show_archived = localStorage.getItem('show_archived') || 'false';
                const show_other_users = localStorage.getItem('show_other_users') || 'true';
                saved_settings += `&show_archived=${show_archived}&show_other_users=${show_other_users}`;
                getRunsTable($(table), `/v2/runs?uri=${uri}&uri_mode=exact&limit=0${saved_settings}`, false, false, true)
            }
```

